export function SiteHeader() {
  const storeName = process.env.NEXT_PUBLIC_STORE_NAME ?? "Trailhead";

  return (
    <header className="border-b border-stone-200 bg-white">
      <div className="mx-auto flex max-w-6xl items-center justify-between gap-6 px-6 py-4">
        <Link href="/" className="flex items-center gap-2 text-lg font-semibold text-brand-dark">
          <Image src="/logo.svg" alt="" width={32} height={32} />
          {storeName}
        </Link>
        <nav aria-label="Main">
          <ul className="flex gap-6 text-sm font-medium">
            {navLinks.map((link) => (
              <li key={link.href}>
                <Link href={link.href} className="hover:text-brand">
                  {link.label}
                </Link>
              </li>
            ))}
          </ul>
        </nav>
      </div>
    </header>
  );
}

const priceFormatter = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
});

const dateFormatter = new Intl.DateTimeFormat("en-US", {
  dateStyle: "medium",
  timeZone: "UTC",
});

// Prices are stored as integer cents so sums never pick up floating-point errors.
export function formatPrice(cents: number): string {
  return priceFormatter.format(cents / 100);
}

// Dates format in UTC so the server and every browser print the same day.
export function formatDate(iso: string): string {
  return dateFormatter.format(new Date(iso));
}

"use client";

import { useRouter } from "next/navigation";
import { useEffect, useRef, type ReactNode } from "react";

// Built for intercepted routes: the modal opens on mount, and closing it in any way
// (the Close button, Escape, or a click on the backdrop) goes back to the page below.
export function Modal({ title, children }: { title: string; children: ReactNode }) {
  const router = useRouter();
  const dialogRef = useRef<HTMLDialogElement>(null);

  useEffect(() => {
    const dialog = dialogRef.current;
    if (dialog && !dialog.open) {
      dialog.showModal();
    }
  }, []);

  return (
    <dialog
      ref={dialogRef}
      aria-label={title}
      onClose={() => router.back()}
      onClick={(event) => {
        if (event.target === event.currentTarget) {
          event.currentTarget.close();
        }
      }}
      className="m-auto w-full max-w-lg rounded-xl p-0 shadow-xl backdrop:bg-black/50"
    >
      <div className="p-6">{children}</div>
      <form method="dialog" className="border-t border-stone-200 px-6 py-3 text-right">
        <button className="rounded-md border border-stone-300 px-3 py-1.5 text-sm font-medium">Close</button>
      </form>
    </dialog>
  );
}
